//! Regression tests for the lock-file reader.

use super::lock_packages;

/// A lock holding one path package, one registry package and one unused key.
const SAMPLE: &str = concat!(
    "# This file is automatically @generated by Cargo.\n",
    "version = 4\n",
    "\n",
    "[[package]]\n",
    "name = \"fixture_template\"\n",
    "version = \"0.1.0\"\n",
    "dependencies = [\n",
    " \"serde\",\n",
    "]\n",
    "\n",
    "[[package]]\n",
    "name = \"serde\"\n",
    "version = \"1.0.219\"\n",
    "source = \"registry+https://github.com/rust-lang/crates.io-index\"\n",
    "checksum = \"deadbeef\"\n",
);

#[test]
fn reads_each_entry_with_its_source() {
    let packages = lock_packages(SAMPLE).expect("the sample lock is readable");

    assert_eq!(
        packages,
        [
            super::LockPackage {
                name: "fixture_template",
                version: "0.1.0",
                source: None,
            },
            super::LockPackage {
                name: "serde",
                version: "1.0.219",
                source: Some("registry+https://github.com/rust-lang/crates.io-index"),
            },
        ],
        "a path entry has no source and a registry entry keeps the one it states",
    );
}

#[test]
fn reads_an_empty_lock_as_no_entries() {
    let packages = lock_packages("version = 4\n").expect("an empty lock is readable");

    assert_eq!(packages, [], "the header alone declares no package");
}

#[test]
fn a_dependency_string_does_not_overwrite_a_field() {
    let lock = concat!(
        "[[package]]\n",
        "name = \"fixture_template\"\n",
        "version = \"0.1.0\"\n",
        "dependencies = [\n",
        " \"name = not-a-value\",\n",
        "]\n",
    );

    let packages = lock_packages(lock).expect("the lock is readable");

    assert_eq!(
        packages.first().map(|package| package.name),
        Some("fixture_template"),
        "the entry's own name is the first assignment and must win",
    );
}

#[test]
fn an_entry_without_a_version_is_an_error() {
    let result = lock_packages("[[package]]\nname = \"fixture_template\"\n");

    assert_eq!(
        result,
        Err("lock entry fixture_template has no version".to_owned()),
        "a malformed entry must not read as a complete one",
    );
}

#[test]
fn an_entry_without_a_name_is_an_error() {
    let result = lock_packages("[[package]]\nversion = \"0.1.0\"\n");

    assert_eq!(
        result,
        Err("lock entry has no name".to_owned()),
        "an unnamed entry must not read as a complete one",
    );
}
